INSERT INTO "capacitacion_curso" ("id", "creado_en", "actualizado_en", "titulo", "descripcion", "estado", "es_refuerzo", "creado_por_id") VALUES (1, '2026-10-22T12:29:46.506755+00:00', '2026-10-22T12:29:46.506767+00:00', 'Fundamentos para reconocer el phishing', 'Curso básico obligatorio: qué es el phishing, cómo identificarlo y cómo reportarlo en PhishGuard.', 'PUBLICADO', FALSE, 1);
INSERT INTO "capacitacion_curso" ("id", "creado_en", "actualizado_en", "titulo", "descripcion", "estado", "es_refuerzo", "creado_por_id") VALUES (2, '2026-10-22T12:29:46.512401+00:00', '2026-10-22T12:29:46.512410+00:00', 'Refuerzo: cayó en una simulación', 'Curso corto que se asigna automáticamente a quien hace clic en una simulación de phishing.', 'PUBLICADO', TRUE, 1);
INSERT INTO "capacitacion_curso" ("id", "creado_en", "actualizado_en", "titulo", "descripcion", "estado", "es_refuerzo", "creado_por_id") VALUES (3, '2026-10-22T12:29:46.518497+00:00', '2026-10-22T12:29:46.518507+00:00', 'Contraseñas seguras y autenticación', 'Cómo crear y proteger contraseñas y por qué activar la verificación en dos pasos.', 'PUBLICADO', FALSE, 1);
INSERT INTO "capacitacion_curso" ("id", "creado_en", "actualizado_en", "titulo", "descripcion", "estado", "es_refuerzo", "creado_por_id") VALUES (4, '2026-10-22T12:29:46.521895+00:00', '2026-10-22T12:29:46.521905+00:00', 'Manejo seguro de archivos adjuntos', 'Qué tipos de archivo son riesgosos y cómo verificar un adjunto antes de abrirlo.', 'PUBLICADO', FALSE, 1);
INSERT INTO "capacitacion_curso" ("id", "creado_en", "actualizado_en", "titulo", "descripcion", "estado", "es_refuerzo", "creado_por_id") VALUES (5, '2026-10-22T12:29:46.525233+00:00', '2026-10-22T12:29:46.525252+00:00', 'Ingeniería social en el trabajo', 'Técnicas de manipulación por teléfono, correo y en persona, y cómo responder ante ellas.', 'PUBLICADO', FALSE, 1);
INSERT INTO "capacitacion_leccion" ("id", "creado_en", "actualizado_en", "curso_id", "orden", "titulo", "contenido_html", "video_url") VALUES (1, '2026-10-22T12:29:46.507438+00:00', '2026-10-22T12:29:46.507451+00:00', 1, 1, '¿Qué es el phishing?', '<p>El <strong>phishing</strong> es un engaño en el que un atacante se hace pasar por una persona o entidad de confianza para obtener contraseñas, datos bancarios o lograr que la víctima abra un archivo malicioso.</p><p>Suele llegar por correo electrónico e imita a bancos, proveedores, servicios de paquetería o incluso a compañeros de trabajo.</p>', '');
INSERT INTO "capacitacion_leccion" ("id", "creado_en", "actualizado_en", "curso_id", "orden", "titulo", "contenido_html", "video_url") VALUES (2, '2026-10-22T12:29:46.507821+00:00', '2026-10-22T12:29:46.507830+00:00', 1, 2, 'Señales de alerta en un correo', '<h3>Revise siempre:</h3><ul><li>El <strong>remitente real</strong>: dominios parecidos como <em>curex-net.ve</em> o <em>curex.net.ve.soporte.com</em>.</li><li><strong>Urgencia o amenazas</strong>: «su cuenta será suspendida hoy».</li><li><strong>Enlaces</strong> cuyo destino no coincide con el texto (pase el cursor sin hacer clic).</li><li><strong>Adjuntos inesperados</strong>: .zip, .exe, .html o documentos que piden «habilitar contenido».</li><li>Saludos genéricos y errores de ortografía.</li></ul>', '');
INSERT INTO "capacitacion_leccion" ("id", "creado_en", "actualizado_en", "curso_id", "orden", "titulo", "contenido_html", "video_url") VALUES (3, '2026-10-22T12:29:46.508116+00:00', '2026-10-22T12:29:46.508127+00:00', 1, 3, 'Qué hacer ante un correo sospechoso', '<ol><li>No haga clic en enlaces ni abra adjuntos.</li><li>No responda ni reenvíe el correo a sus compañeros.</li><li>Repórtelo desde <strong>PhishGuard → Reportar correo</strong>.</li><li>Si ya hizo clic o escribió su contraseña, cámbiela y avise de inmediato al Departamento de Soporte Técnico y Sistemas.</li></ol><blockquote>Reportar a tiempo protege a toda la organización.</blockquote>', '');
INSERT INTO "capacitacion_leccion" ("id", "creado_en", "actualizado_en", "curso_id", "orden", "titulo", "contenido_html", "video_url") VALUES (4, '2026-10-22T12:29:46.512810+00:00', '2026-10-22T12:29:46.512821+00:00', 2, 1, '¿Qué acaba de pasar?', '<p>Hizo clic en un correo de <strong>simulación</strong> preparado por el Departamento de Soporte Técnico y Sistemas. No hubo ningún daño, pero un atacante real habría podido robar su información.</p><p>Repase las señales de alerta y, la próxima vez, use el botón <strong>Reportar correo</strong>.</p>', '');
INSERT INTO "capacitacion_leccion" ("id", "creado_en", "actualizado_en", "curso_id", "orden", "titulo", "contenido_html", "video_url") VALUES (5, '2026-10-22T12:29:46.518776+00:00', '2026-10-22T12:29:46.518786+00:00', 3, 1, 'Características de una contraseña segura', '<p>Use frases largas (12 caracteres o más), únicas para cada servicio y difíciles de adivinar.</p>', '');
INSERT INTO "capacitacion_leccion" ("id", "creado_en", "actualizado_en", "curso_id", "orden", "titulo", "contenido_html", "video_url") VALUES (6, '2026-10-22T12:29:46.518986+00:00', '2026-10-22T12:29:46.518995+00:00', 3, 2, 'Gestores de contraseñas', '<p>Un gestor de contraseñas genera y guarda claves distintas para cada servicio, de modo que solo debe recordar una.</p>', '');
INSERT INTO "capacitacion_leccion" ("id", "creado_en", "actualizado_en", "curso_id", "orden", "titulo", "contenido_html", "video_url") VALUES (7, '2026-10-22T12:29:46.522148+00:00', '2026-10-22T12:29:46.522157+00:00', 4, 1, 'Extensiones peligrosas', '<p>Desconfíe de archivos .exe, .js, .vbs, .scr, .zip o documentos que piden «habilitar macros».</p>', '');
INSERT INTO "capacitacion_leccion" ("id", "creado_en", "actualizado_en", "curso_id", "orden", "titulo", "contenido_html", "video_url") VALUES (8, '2026-10-22T12:29:46.522343+00:00', '2026-10-22T12:29:46.522351+00:00', 4, 2, 'Verificar antes de abrir', '<p>Si no esperaba el adjunto, confirme con el remitente por otro medio (teléfono o en persona) antes de abrirlo.</p>', '');
INSERT INTO "capacitacion_leccion" ("id", "creado_en", "actualizado_en", "curso_id", "orden", "titulo", "contenido_html", "video_url") VALUES (9, '2026-10-22T12:29:46.525723+00:00', '2026-10-22T12:29:46.525737+00:00', 5, 1, '¿Qué es la ingeniería social?', '<p>Es la manipulación de personas para que entreguen información o realicen acciones que favorecen a un atacante.</p>', '');
INSERT INTO "capacitacion_leccion" ("id", "creado_en", "actualizado_en", "curso_id", "orden", "titulo", "contenido_html", "video_url") VALUES (10, '2026-10-22T12:29:46.526040+00:00', '2026-10-22T12:29:46.526060+00:00', 5, 2, 'Cómo responder', '<p>Verifique la identidad de quien solicita información, no comparta datos confidenciales por teléfono y reporte los intentos sospechosos.</p>', '');
